export const meta = { name: 'p', description: 'd' }
const out = {}
const attempt = (name, f) => { try { out[name] = 'ok: ' + String(f()).slice(0, 60) } catch (e) { out[name] = 'threw ' + (e && e.constructor && e.constructor.name) + ': ' + (e && e.message) } }
attempt('Date.now()', () => Date.now())
attempt('new Date()', () => new Date())
attempt('Date()', () => Date())
attempt('new Date(0)', () => new Date(0).toISOString())
attempt('new Date(undefined)', () => new Date(undefined).getTime())
attempt("Date['now']()", () => Date['now']())
attempt('const { now } = Date', () => { const { now } = Date; return now() })
attempt('new (Date)()', () => { const D = Date; return new D() })
attempt('Date.parse', () => Date.parse('2026-01-01T00:00:00Z'))
attempt('Date.UTC', () => Date.UTC(2026, 0, 1))
attempt('Math.random()', () => Math.random())
attempt("Math['random']()", () => Math['random']())
attempt('performance.now()', () => performance.now())
attempt('crypto.randomUUID()', () => crypto.randomUUID())
attempt('eval', () => eval('1 + 1'))
attempt('indirect eval', () => (0, eval)('1 + 1'))
attempt('new Function', () => new Function('return 2')())
attempt('setTimeout string', () => setTimeout('1', 0))
attempt('structuredClone', () => JSON.stringify(structuredClone({ a: 1 })))
attempt('JSON', () => JSON.stringify({ a: [1] }))
attempt('Intl', () => typeof Intl)
attempt('new Intl.DateTimeFormat().format()', () => new Intl.DateTimeFormat('en').format())
attempt('RegExp', () => /a/.test('a'))
attempt('WeakRef', () => typeof WeakRef)
attempt('Atomics.wait', () => typeof Atomics)
return out
